'use strict';
const M=Mapping,KEY=M.KEY;
const memoryData=new Map();let memoryMode=false;const memoryStorage={getItem:k=>memoryData.get(k)||null,setItem:(k,v)=>memoryData.set(k,v)};
let storage;try{storage=window.localStorage;const probe='mmo-storage-probe';storage.setItem(probe,'1');storage.removeItem(probe);}catch(e){if(storage)for(const k of [M.KEY,M.LEGACY_KEY,'mmo-mapping-v2-last-backup']){try{const v=storage.getItem(k);if(v)memoryStorage.setItem(k,v);}catch(ignore){}}storage=memoryStorage;memoryMode=true;}
let db,legacy=null,needsChoice=false,migrationRequired=false,storageError='';
let persistedRaw;try{persistedRaw=storage.getItem(KEY);}catch(e){persistedRaw=null;}
try{({db,legacy,needsChoice,migrationRequired=false}=M.loadState(storage));}catch(e){db=M.seed();needsChoice=true;storageError='本地数据暂不可读取：'+e.message+'。请先导出原始备份，不会自动覆盖。';}
let page='home',role='hr',queryState={},indexState={},projectState={id:'G-A2',period:'2024',tab:'org',expanded:[],highlight:''},draftId='',intakeText=M.DEMO,formError='',routeHistory=[],modalStack=[],lastSummary=null;
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const act=(a,t,extra='',cls='link')=>`<button type="button" class="${cls}" data-action="${a}" ${extra}>${t}</button>`;
const info=key=>act('help','ⓘ',`data-key="${key}" aria-label="说明：${esc(helpRegistry[key]?.title||key)}"`,'info');
const action=(a,t,extra='',cls='link',help=a)=>`<span class="action-pair">${act(a,t,extra,cls)}${helpRegistry[help]?info(help):''}</span>`;
const tag=(t,c='')=>`<span class="badge ${c}">${esc(t)}</span>`;
const project=id=>db.projects.find(x=>x.id===id),person=id=>db.people.find(x=>x.id===id),evidence=id=>db.evidence.find(x=>x.id===id),jobs=id=>M.publishedJobs(db).filter(j=>j.personId===id);
const caps=j=>M.capabilitiesFor(db,j),timeText=j=>M.timeText(j,db);
const fieldValue=(j,f)=>M.fieldClaims(db,j.id,f).at(-1)?.value||'未知（有效字段依据不足）';
const claimLinks=ids=>(ids||[]).map(id=>{const c=db.fieldClaims.find(c=>c.id===id);return c?action('claim',esc(M.fieldLabels[c.field])+' · '+esc(c.basis),`data-id="${id}"`,'link','evidence'):'';}).join(' ');
const pending=()=>db.drafts.filter(d=>['待审核','部分发布'].includes(d.status)).length+db.tasks.filter(t=>t.status==='待核验').length;
function persistState(next){if(storage.getItem(KEY)!==persistedRaw)throw new Error('其他标签页已更新存档，已阻止覆盖；请先导出当前内存副本，再刷新合并');const raw=JSON.stringify(next);storage.setItem(KEY,raw);persistedRaw=raw;storageError='';}
function save(){if(needsChoice||migrationRequired)return false;try{persistState(db);return true;}catch(e){storageError='保存失败：'+e.message+'。请导出当前数据。';toast(storageError);return false;}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',5000);}
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function archive(){if(memoryMode)download('MMO_Mapping_重置前备份.json',JSON.stringify(db,null,2),'application/json');const key='mmo-mapping-v2-backup-'+Date.now();storage.setItem(key,JSON.stringify(db));storage.setItem('mmo-mapping-v2-last-backup',key);return key;}
function routeSnapshot(){return M.clone({page,queryState,indexState,projectState,modals:modalStack});}
function go(p,push=false){if(push)routeHistory.push(routeSnapshot());page=p;formError='';modalStack=[];$('#detail').close();render();window.scrollTo(0,0);}
function openProject(id,period='all',highlight=''){routeHistory.push(routeSnapshot());projectState={id,period,tab:'org',expanded:[],highlight};if(highlight)projectState.expanded=[...new Set(M.projectJobs(db,id).filter(j=>j.personId===highlight).map(j=>j.team))];go('project');}
function back(){const r=routeHistory.pop();if(!r)return go('projects');({page,queryState,indexState,projectState}=r);modalStack=r.modals||[];render();if(modalStack.length)renderModal();else $('#detail').close();}
function projectLink(id,year='all',pid=''){return action('project',esc(project(id)?.name??'未知项目'),`data-id="${esc(id)}" data-period="${year}" data-person="${pid}"`,'link','projects');}
function evidenceLink(ids){return (Array.isArray(ids)?ids:[ids]).filter(Boolean).map(id=>action('evidence','原文 '+esc(id),`data-id="${esc(id)}"`)).join(' ');}
function stateTags(x){return `${tag(x.processStatus||'已发布','green')} ${tag(x.factStatus||M.SINGLE,'amber')} ${tag('虚构演示')}`;}
function bodyHeading(title,sub){return `<div class="heading"><div><h1>${title}</h1><p class="muted">${sub}</p></div>${role==='hr'&&page!=='intake'?action('nav','＋ 录入新情报','data-page="intake"','btn','extract'):''}</div>`;}
function render(){if(migrationRequired)return renderUpgrade();if(needsChoice)return renderMigration();if(role==='biz'&&['review','logs','intake','data'].includes(page))page='home';const names={home:'情报驾驶舱',requirements:'需求工作台',longlist:'需求长名单',org:'组织分析与建议',flow:'人才流动与能力',projects:'公司与项目',project:'项目组织观察',search:'关联人才查询',intake:'录入新情报',review:'审核与待办',logs:'版本与更新',pool:'我的人才池',about:'方案说明',data:'数据与版本迁移'};
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">M</span> MMO Mapping</div><div class="side-label">核心策划人才观察 · V3.4.0</div><nav class="nav">${[['home','◫','情报驾驶舱'],['search','⌕','关联人才查询'],['requirements','需','需求工作台'],['longlist','☰','需求长名单'],['flow','⇄','人才流动与能力'],['org','◎','组织分析与建议'],['projects','▦','公司与项目'],['review','☷','审核与待办'],['pool','◇','我的人才池'],['logs','↺','版本与更新'],['data','⇩','数据与备份']].filter(([p])=>role==='hr'||!['review','logs','data'].includes(p)).map(([p,i,t])=>act('nav',`<span class="nav-icon">${i}</span>${t}${p==='review'?` <span class="count">${pending()}</span>`:p==='pool'&&M.poolItems(db).some(i=>i.overdue)?` <span class="count">${M.poolItems(db).filter(i=>i.overdue).length}</span>`:''}`,`data-page="${p}"`,page===p||p==='projects'&&page==='project'?'active':'')).join('')}</nav><div class="side-bottom">字段证据 · 判断分层 · 流向洞察<br>虚构演示 / 数据版本 V${db.revision}<br>${act('nav','方案说明 ↗','data-page="about"')}</div></aside><main class="main"><header class="topbar"><span class="eyebrow">WORKSPACE / MMO TALENT</span><div class="row">${tag('虚构演示','amber')}<select id="role" class="role" aria-label="切换演示视角"><option value="hr" ${role==='hr'?'selected':''}>HR 工作台 · 视角模拟</option><option value="biz" ${role==='biz'?'selected':''}>业务洞察 · 视角模拟</option></select>${info('role')}</div></header><div class="content">${bodyHeading(names[page],page==='home'?'市场信号 → 组织变化 → 人才窗口 → 下一步行动；每一步都能回到原文。':'同一组事实 · 保留时间、依据与不确定性')}<div class="notice">${tag('V3.4.0')}<span>${storageError||(memoryMode?'临时体验模式：浏览器禁止本地存储，关闭页面会丢失进度。请在数据与备份中导出 JSON，下次导入恢复。':'进度仅保存在本浏览器；同一浏览器同站点的标签页共享，其他访问者互不影响。文件移动或更换浏览器请用 JSON 迁移。')} 观察日 ${db.observationDate} · 全部资料虚构 · 视角模拟非账号安全权限。</span></div>${({home,projects:projectsView,project:projectView,search:searchView,intake,review,logs:logsView,pool:poolBoard,about,data:dataView,requirements:requirementsView,longlist:longlistView,flow:flowView,org:orgAnalysisView}[page])()}<footer class="footer"><span>MMO Mapping V3.4.0 · 样本观察，判断与事实分层，不推断求职意向</span><span>${act('nav','方案与操作说明','data-page="about"')} ${role==='hr'?act('nav','数据备份 / 重置','data-page="data"'):''}</span></footer></div></main></div>`;
}
function renderUpgrade(){const preview=M.migrateDatabase(db);$('#app').innerHTML=`<main class="migration"><div class="brand dark">MMO Mapping V3.4.0</div><section class="panel section-space"><h1>旧版本存档迁移预览（→ V3.4.0）</h1><p>保留 ${db.people.length} 位人员、${db.jobs.length} 段任职、${db.logs.length} 条审核日志与全部审核进度。迁移后共 ${preview.people.length} 位人员、${preview.jobs.length} 段任职（并入 V3.1 扩充虚构样本）、${preview.fieldClaims.length} 条字段主张，补齐 V3.2 需求集合（保存口径版本、冻结交付、反馈与需求人才池）。已有事实、审核进度和旧交付不改写；人才池中的自由文本需求不会自动合并。</p><div class="hint">旧来源日期异常 ${preview.evidence.filter(e=>e.quarantined).length} 份：保留原始文本和日期，隔离于有效查询与组织；后续补证。旧日期不自动改写。历史初始化材料不计新采集。</div><div class="actions">${action('exportV2','先导出原始 V2 JSON','','btn secondary')}${act('upgrade','保存可恢复备份并迁移 V3.4.0','','btn')}</div><p class="muted">确认前不写入任何存储。V1 原存档不变。</p></section></main>`;}
function renderMigration(){ $('#app').innerHTML=`<main class="migration"><div class="brand dark"><span class="brandmark">M</span> MMO Mapping V2</div><section class="panel section-space"><span class="eyebrow">保留旧记录，再进入新演示</span><h1 class="section-space">${legacy?'检测到 V1 本地记录':'本地数据需要检查'}</h1><p>V2 使用另一个虚构世界：曜辰互动的《玄霄》《云境》，以及沧澜游戏的《灵域传说》。不会把旧人物改名，也不会把两组数据混在一起。</p><div class="hint">V1 原存储键不修改。先导出旧记录可作为独立备份；加载 V2 只创建新的存储键。${esc(storageError)}</div><div class="actions">${action('exportLegacy','导出 V1 原始备份','','btn secondary')}${act('loadV2','保留 V1，加载 V2 示例','','btn')}${info('migration')}</div></section></main>`;}
function home(){return cockpit();}
function projectCards(list){return list.map(p=>`<article class="project-card"><div class="row spread"><span class="project-top">${p.name[0]}</span>${tag(M.stageAt(p,2026))}</div><h3>${projectLink(p.id,'2024')}</h3><p class="muted">${db.companies.find(c=>c.id===p.companyId).name} / ${p.studio}<br>${p.genre} · ${p.platform}</p><hr class="divider"><p class="small">全部时期已识别 <b>${M.projectPeople(db,p.id).length}</b> 人 · 待核验关系 ${M.projectRelations(db,p.id).filter(r=>r.processStatus==='待核验').length} 条</p>${action('project','查看组织 →',`data-id="${p.id}" data-period="2024"`,'link','projects')}</article>`).join('');}
function projectsView(){const filtered=db.projects.filter(p=>(!indexState.company||p.companyId===indexState.company)&&(!indexState.genre||p.genre===indexState.genre)&&(!indexState.phase||p.phases.some(s=>s.name===indexState.phase))&&(!indexState.followed||db.follows.includes(p.id))&&(!indexState.changed||db.events.some(e=>e.projectId===p.id)));return `<section class="panel"><div class="panel-head"><h2>公司 / 项目索引</h2>${info('company')}</div><form id="projectFilters" class="filters"><label class="field">公司<select name="company"><option value="">全部公司</option>${db.companies.map(c=>`<option value="${c.id}" ${indexState.company===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><label class="field">MMO 子品类<select name="genre"><option value="">全部子品类</option>${db.projects.map(p=>`<option ${indexState.genre===p.genre?'selected':''}>${p.genre}</option>`).join('')}</select></label><label class="field">阶段（当前 / 历史）<select name="phase"><option value="">全部阶段</option>${[...new Set(db.projects.flatMap(p=>p.phases.map(s=>s.name)))].map(n=>`<option ${indexState.phase===n?'selected':''}>${n}</option>`).join('')}</select></label><label><input name="followed" type="checkbox" ${indexState.followed?'checked':''}>仅关注</label><label><input name="changed" type="checkbox" ${indexState.changed?'checked':''}>有收录事件</label><button class="btn secondary">应用筛选</button></form><div class="project-grid section-space">${projectCards(filtered)||'<p class="empty">没有符合筛选的项目。</p>'}</div></section><section class="panel section-space"><div class="panel-head"><h2>公司分布与跨公司轨迹</h2>${info('company')}</div><div class="company-grid">${db.companies.map(c=>{const gs=db.projects.filter(p=>p.companyId===c.id),ids=new Set(M.publishedJobs(db).filter(j=>gs.some(g=>g.id===j.projectId)).map(j=>j.personId));return `<div class="record"><h3>${c.name}</h3><p>${gs.length} 个项目 · ${ids.size} 位去重人员</p>${gs.map(p=>projectLink(p.id)).join('　')}</div>`}).join('')}</div>${db.people.filter(p=>new Set(jobs(p.id).map(j=>project(j.projectId).companyId)).size>1).map(p=>`<div class="task"><span>${action('person',p.name,`data-id="${p.id}"`)}　${jobs(p.id).sort((a,b)=>a.start-b.start).map(j=>`${db.companies.find(c=>c.id===project(j.projectId).companyId).name} / ${project(j.projectId).name} ${j.start}`).join(' → ')}</span>${info('person')}</div>`).join('')||'<p class="muted">当前没有已收录跨公司轨迹。</p>'}</section>${projectLinksPanel('')}`;}
function selectedYears(){const p=project(projectState.id);if(projectState.period==='all')return null;if(projectState.period.startsWith('phase:')){const s=p.phases[+projectState.period.split(':')[1]];return Array.from({length:s.end-s.start+1},(_,i)=>s.start+i);}return [+projectState.period];}
function selectedRows(rows){const years=selectedYears();return rows.filter(r=>!years||years.some(y=>db.jobs.some(j=>j.id===r.id)?M.projectJobs(db,r.projectId,y).some(j=>j.id===r.id):M.active(r,y)));}
function projectView(){const p=project(projectState.id),js=selectedRows(M.projectJobs(db,p.id)),rs=selectedRows(M.projectRelations(db,p.id)),years=selectedYears(),year=years?.length===1?years[0]:'all';return `<div class="breadcrumbs">${act('back','← 返回上一视图')}<span>／</span>${act('nav','公司与项目','data-page="projects"')}<span>／ ${db.companies.find(c=>c.id===p.companyId).name} ／ ${p.name}</span></div><section class="panel project-header"><div class="panel-head"><div><h2>《${p.name}》</h2><p class="muted">${p.studio} · ${p.genre} · ${p.platform} · 启动 ${p.start}</p></div>${action('follow',db.follows.includes(p.id)?'已关注 ✓':'＋ 关注项目',`data-id="${p.id}"`,'btn secondary')}</div><div class="project-metrics"><span>所选时期已识别 <b>${new Set(js.map(j=>j.personId)).size}</b> 人</span><span>已发布任职 <b>${js.length}</b> 段</span><span>独立交叉核验 <b>${js.filter(j=>j.factStatus==='已独立交叉核验').length}</b> 段</span><span>待核验关系 <b>${rs.filter(r=>r.processStatus==='待核验').length}</b> 条</span></div><p class="muted">最近资料审核记录：${js.length?js.map(j=>j.reviewedAt).sort().at(-1).slice(0,10):'未收录'}；不代表现实事实已核验。实际编制未知。</p><div class="row spread"><div class="row"><label class="field">查看时期<select id="period" aria-label="项目组织时期"><option value="all" ${projectState.period==='all'?'selected':''}>全部已收录时期</option><optgroup label="阶段范围">${p.phases.map((s,i)=>`<option value="phase:${i}" ${projectState.period==='phase:'+i?'selected':''}>${s.name} · ${s.start}–${s.end}</option>`).join('')}</optgroup><optgroup label="指定年份（月份未知）">${Array.from({length:2026-p.start+1},(_,i)=>p.start+i).map(y=>`<option value="${y}" ${projectState.period===String(y)?'selected':''}>${y} 年 · ${M.stageAt(p,y)}</option>`).join('')}</optgroup></select></label>${info('period')}</div>${evidenceLink(p.evidenceId)}</div><div class="tabs section-space">${[['org','组织结构'],['timeline','架构演变'],['history','历史变化'],['related','关联人才']].map(([id,name])=>act('projectTab',name,`data-tab="${id}"`,projectState.tab===id?'active':'')).join('')}</div></section>${projectState.tab==='org'?orgView(p,js,rs,year):projectState.tab==='timeline'?timelineView(p):projectState.tab==='history'?historyView(p):relatedView(p,js,year)}`;}
function orgView(p,js,rs,year){const teams=[...new Set(js.map(j=>j.team))];return `<section class="panel section-space"><div class="panel-head"><h2>核心岗位骨架</h2>${info('projects')}</div><p class="muted">模块分组不表示真实汇报层级。点击模块展开当期已收录成员；未收录人数未知。</p>${teams.length?`<div class="org-grid">${teams.map(team=>{const members=js.filter(j=>j.team===team),open=projectState.expanded.includes(team);return `<section class="org-module ${members.some(j=>j.personId===projectState.highlight)?'highlight':''}"><div class="row spread">${act('team',`${open?'−':'＋'} 展开${esc(team)}`,`data-team="${esc(team)}" aria-expanded="${open}"`,'team-button')}${info('team')}</div><p class="muted">${new Set(members.map(j=>j.personId)).size} 位已收录 · 总编制未知</p>${open?members.map(j=>`<article class="org-person ${j.personId===projectState.highlight?'highlight':''}"><div class="row spread">${action('person',esc(person(j.personId).name),`data-id="${j.personId}"`)}${action('job','岗位详情',`data-id="${j.id}" data-year="${year}"`,'link','evidence')}</div><strong>${esc(M.roleAt(j,year,db))}</strong><p class="muted">${timeText(j)}<br>${esc(fieldValue(j,'module'))} · ${esc(fieldValue(j,'scope'))}</p>${stateTags(j)}</article>`).join(''):''}<div class="actions">${action('teamHistory','历史任职人员',`data-team="${esc(team)}" data-id="${p.id}"`,'link','related')}</div></section>`}).join('')}</div>`:'<div class="empty">该时期未收录足够组织信息。不会复制当前团队或标注真实岗位空缺。</div>'}<hr class="divider"><div class="panel-head"><h3>有专门线索的人员关系</h3>${info('relation')}</div><div class="legend"><span class="solid-sample"></span> 实线：演示材料经人工批准显示的合作 / 汇报 <span class="dashed-sample"></span> 虚线：仅待核验线索</div><p class="muted">实线表示人工批准演示材料，不表示现实事实或来源独立性已核实。同项目关系单独列出，不画汇报线。</p>${rs.filter(r=>r.type!=='同项目').map(r=>`<div class="relation-edge ${r.processStatus==='待核验'?'pending':''}"><div class="relation-node">${action('person',person(r.subjectId).name,`data-id="${r.subjectId}"`)}<small>${js.some(j=>j.personId===r.subjectId)?'当期任职已收录':'仅有关系线索；该项目任职未确认'}</small></div>${act('relation',`${r.processStatus==='待核验'?'? 待核验：':''}${r.type}${r.type==='直接汇报'?' →':' —'}`,`data-id="${r.id}" aria-label="${r.processStatus==='待核验'?'核验':'查看'}：${person(r.subjectId).name}与${person(r.objectId).name}的${r.type}"`,'relation-line')}<div class="relation-node">${action('person',person(r.objectId).name,`data-id="${r.objectId}"`)}<small>${timeText(r)}</small></div></div>`).join('')||'<p class="muted">所选时期没有可绘制的人际关系证据，不自动连线。</p>'}${rs.filter(r=>r.type==='同项目').map(r=>`<p class="muted">同项目：${person(r.subjectId).name} / ${person(r.objectId).name} · ${timeText(r)} ${action('relation','关系依据',`data-id="${r.id}"`)}</p>`).join('')}</section>`;}
function historyView(p){const [before,after]=M.comparisonYears(db,p.id,projectState.period),years=selectedYears(),events=db.events.filter(e=>(e.projectId===p.id||e.relatedProjectId===p.id)&&(!years||years.includes(+e.date.slice(0,4))));return `<section class="panel section-space"><div class="panel-head"><h2>项目阶段与人员变化</h2>${info('compare')}</div><div class="row">${p.phases.map(s=>tag(s.start+'–'+s.end+' '+s.name)).join('')}</div><div class="actions">${action('compare',`${before} / ${after} 组织对照`,`data-id="${p.id}"`,'btn secondary','compare')}</div>${events.map(e=>`<article class="record"><span class="muted">发生 ${e.date} ／公开 ${e.published} ／采集 ${e.collected}</span><h3 class="section-space">${esc(e.title)}</h3><p>${esc(e.fact)}</p><p class="muted">待核验：${esc(e.gap)}</p><div class="actions">${action('event','查看变化与受影响记录',`data-id="${e.id}"`,'link','compare')}${evidenceLink(e.evidenceIds)}</div></article>`).join('')||'<p class="empty">所选时期未收录人员事件。可查看所选时期的组织对照；不能据此断言没有变动。</p>'}</section>`;}
function relatedView(p,js,year){return `<section class="panel section-space"><div class="panel-head"><h2>所选时期的项目人才</h2>${info('related')}</div><p class="muted">按唯一人员去重。同期同项目不等于直接合作或汇报。</p>${[...new Set(js.map(j=>j.personId))].map(id=>personCard(person(id),true)).join('')||'<div class="empty">暂无该时期人才记录。</div>'}</section>`;}
function personCard(p,compact=false,match=null){const js=jobs(p.id).filter(j=>!match||match.jobIds.includes(j.id)).sort((a,b)=>a.start-b.start);return `<article class="record"><div class="record-top"><div class="row"><span class="avatar">${p.name.slice(-1)}</span><div><h3>${action('person',p.name,`data-id="${p.id}"`)}</h3><span class="muted">${p.id} · ${match?(match.timeConfirmed?'命中':'时间待核验候选'):'已发布'}经历 ${js.length} 段</span></div></div>${action('pool',db.pool.includes(p.id)?'已加入人才池 ✓':'＋ 加入人才池',`data-id="${p.id}"`,'btn secondary')}</div>${compact?'':`<div class="path">${js.map(j=>`<div class="pathnode"><strong>${projectLink(j.projectId,j.start,p.id)} · ${esc(M.roleAt(j,queryState.year||'all',db))}</strong><small>${timeText(j)} · ${esc(fieldValue(j,'module'))} · ID ${j.id}</small>${caps(j).map(c=>tag(c.domain+' / '+c.scope,'green')).join(' ')}${evidenceLink(j.evidenceIds)}</div>`).join('')}</div>`}${match?match.groups.map(g=>`<div class="hint section-space"><strong>命中条件：${esc(g.label)}</strong><p>任职 ${g.jobIds.map(esc).join('、')}</p>${claimLinks(g.claimIds)} ${evidenceLink(g.evidenceIds)}</div>`).join('')+match.uncertainties.map(x=>`<p class="muted">${esc(x)}</p>`).join(''):'<p class="muted">任职与能力分别据原文收录；此处未执行战斗＋主策组合查询。</p>'}${tag('原文明确但单一来源','amber')}</article>`;}
function searchView(){const result=M.queryMatches(db,queryState);return `<section class="panel"><div class="panel-head"><h2>从经历出发，组合查询</h2>${info('query')}</div><p class="hint">同一个人：经历①（公司＋项目＋时期＋能力／战斗职责共同满足）∩ 经历②（曾任主策）。选择“同一段经历同时满足”时合并两组。结束未知不等于确认仍在职。</p><form id="searchForm"><div class="searchbox"><input name="text" aria-label="人才查询条件" value="${esc(queryState.text||'')}" placeholder="姓名、项目，或有战斗经验且做过主策"><button class="btn">查询人才 →</button></div><div class="checks"><label><input name="combat" type="checkbox" ${queryState.combat?'checked':''}>有 MMO 战斗职责</label><label><input name="chief" type="checkbox" ${queryState.chief?'checked':''}>做过主策</label><label class="field">条件组合<select name="mode"><option value="any">跨经历组合</option><option value="same" ${queryState.mode==='same'?'selected':''}>同一段经历同时满足</option></select></label><select name="company" aria-label="筛选公司"><option value="">全部公司</option>${db.companies.map(c=>`<option value="${c.id}" ${queryState.company===c.id?'selected':''}>${c.name}</option>`).join('')}</select><select name="project" aria-label="筛选项目"><option value="">全部项目</option>${db.projects.map(p=>`<option value="${p.id}" ${queryState.project===p.id?'selected':''}>${p.name}</option>`).join('')}</select><select name="year" aria-label="筛选任职年份"><option value="">全部年份</option>${Array.from({length:9},(_,i)=>2018+i).map(y=>`<option value="${y}" ${String(queryState.year)===String(y)?'selected':''}>${y}年（结束未知仅最近已知）</option>`).join('')}</select><select name="capability" aria-label="筛选能力"><option value="">全部能力</option>${['战斗体系','经济系统','世界与内容','社交与帮会'].map(c=>`<option ${queryState.capability===c?'selected':''}>${c}</option>`).join('')}</select></div></form><div class="row spread"><b>找到 ${result.length} 位已发布人员</b>${act('clearQuery','清空条件')}</div>${result.map(r=>personCard(r.person,false,r)).join('')||'<div class="empty">没有符合条件的已发布记录。请调整条件或审核新情报；缺证不等于没有能力。</div>'}</section>`;}
function intake(){const sample=M.SAMPLES.find(x=>x.text===intakeText);return `<section class="panel"><div class="panel-head"><h2>模拟抽取 · 三份完整虚构材料</h2>${info('extract')}</div><p class="muted">使用预设适配层，无真实 AI 或网络调用。第一条补历史职责，第二条仅补2022–2023头衔，第三条保留花名与岗位冲突。未知文本不会套用答案。</p><div class="tabs">${M.SAMPLES.map(s=>act('useDemo',s.title,`data-kind="${s.id}"`)).join('')}</div>${sample?`<p class="muted">来源：${sample.kind} · 发布 ${sample.published} · 采集 ${db.observationDate} · 独立性未核实</p>`:''}<form id="extractForm"><label class="field">虚构原文<textarea name="sourceText" id="sourceText" required>${esc(intakeText)}</textarea></label>${formError?`<p class="error" role="alert">${esc(formError)}</p>`:''}<div class="actions"><button class="btn">模拟抽取并生成待审核提案 →</button>${info('extract')}${action('nav','查看 Prompt','data-page="about"','link','evidence')}</div></form></section>`;}

function tasksHtml(){return db.drafts.filter(d=>['待审核','部分发布'].includes(d.status)).map(d=>`<div class="task"><div><h3>${d.name} · ${d.status}</h3><span class="muted">${d.facts.filter(f=>['待审核','待核验'].includes(f.status)).length} 条事实仍待处理</span></div>${action('draft','审核提案 →',`data-id="${d.id}"`,'link','review')}</div>`).join('')+db.tasks.filter(t=>t.status==='待核验').map(t=>`<div class="task"><div><h3>${esc(t.title)}</h3><span class="muted">${esc(t.reason)} · Owner ${t.owner}</span></div>${action(t.relationId?'relation':'task','查看任务',`data-id="${t.relationId||t.id}"`,'link','correction')}</div>`).join('')||'<p class="empty">暂无待处理事项。</p>';}
function review(){const d=db.drafts.find(d=>d.id===draftId&&['待审核','部分发布'].includes(d.status));return `${d?draftView(d):''}<section class="panel section-space"><div class="panel-head"><h2>待审核与核验任务</h2>${info('review')}</div>${tasksHtml()}<hr class="divider"><h3>已处理提案</h3>${db.drafts.filter(d=>!['待审核','部分发布'].includes(d.status)).map(d=>`<div class="task"><span>${d.name} · ${d.status}</span>${action('rawDraft','原文 / 审核结果',`data-id="${d.id}"`,'link','review')}</div>`).join('')||'<p class="muted">暂无</p>'}</section>`;}
function draftView(d){return `<section class="panel"><div class="panel-head"><h2>逐条审核 · ${d.name}</h2>${info('review')}</div><div class="quote">${esc(d.text)}</div><form id="reviewForm"><input name="draftId" type="hidden" value="${d.id}"><label class="field section-space">人员 ID 匹配<select name="personId">${d.mode==='ambiguous'?'<option value="">身份未知（仅暂缓或拒绝）</option>':''}${db.people.map(p=>`<option value="${p.id}" ${d.personId===p.id?'selected':''}>${p.id} · ${p.name}${p.id==='P-A01'?'（名称匹配候选，待人审）':''}</option>`).join('')}</select></label><p class="muted">不根据姓名自动合并。此轮只处理库内现有 ${db.people.length} 位演示人物；若无法匹配，暂不发布。</p>${d.facts.map((f,i)=>{const c=d.mode==='ambiguous'?f.comparison:M.classify(db,f,d.personId),done=['已发布','已拒绝'].includes(f.status);return `<article class="record"><div class="record-top"><h3>${i+1}. ${f.kind==='relation'?'关系候选：同项目':project(f.value.projectId).name+' · '+f.value.role}</h3>${tag(done?f.status:c.action,c.action.includes('冲突')?'amber':'green')}</div><p class="muted">${esc(f.note)}</p><div class="quote">${esc(f.quote)}</div>${done?'<p class="muted">此项已处理，本次不会重复写入。</p>':`<label class="field section-space">此项处理<select name="decision${i}">${[['accept','确认写入 / 修正后确认'],['defer','暂缓待核验'],['reject','拒绝提取']].map(([v,t])=>`<option value="${v}" ${f.decision===v?'selected':''}>${t}</option>`).join('')}</select></label>${f.kind!=='relation'?`<div class="formgrid section-space"><label class="field">岗位原文<input value="${esc(f.value.rawRole||f.value.role)}" readonly></label><label class="field">岗位记录<input name="role${i}" value="${esc(f.value.role)}" required></label><label class="field">开始年份<input name="start${i}" type="number" min="2018" max="2026" value="${f.value.start??''}" ${d.mode==='ambiguous'?'disabled':'required'}></label><label class="field">结束年份（空白为未知）<input name="end${i}" type="number" min="2018" max="2026" value="${f.value.end??''}"></label></div>${f.value.domain?`<label class="checks"><span><input name="cap${i}" type="checkbox" ${f.value.capability?'checked':''}>保留基于职责的 ${f.value.domain} 能力</span></label>`:''}`:''}<label class="field section-space">重叠时的处理方式<select name="overlap${i}"><option value="defer">有冲突则暂缓，保留证据</option><option value="transition">同年岗位转换（须说明依据）</option><option value="parallel">跨项目兼职（保持待核验）</option></select></label><label class="field section-space">人工修订 / 审核理由<input name="note${i}" value="${esc(f.reviewNote||'')}" placeholder="字段修订或重叠判断时必填"></label>`}</article>`}).join('')}<label class="checks"><span><input name="confirmed" type="checkbox" ${d.mode==='ambiguous'?'':'required'}>我已核对人员身份、逐项处理及原文依据；发布不代表独立交叉核验。</span></label>${formError?`<div class="error" role="alert">${esc(formError)}</div>`:''}<div class="actions"><button class="btn">发布已确认项，保留待核验项</button>${info('publish')}</div></form></section>`;}
function logsView(){return `<section class="panel"><div class="panel-head"><h2>数据版本 V${db.revision}</h2><div class="row">${db.logs.some(l=>l.before&&!l.undone)?action('undo','撤销最近一次变更','','btn secondary','logs'):''}${info('logs')}</div></div>${[...db.logs].reverse().map(l=>`<article class="record"><h3>V${l.revision} · ${l.type} ${l.undone?'（已撤销）':''}</h3><p>${esc(l.reason)}</p><p class="muted">记录时间 ${new Date(l.date).toLocaleString('zh-CN')} · ${l.actor}</p><div class="tablewrap"><table><thead><tr><th>对象 / 字段</th><th>旧值</th><th>新值</th><th>生效</th></tr></thead><tbody>${l.changes.map(c=>`<tr><td>${esc(c.objectId)}<br>${esc(c.field)}</td><td><details><summary>查看旧值</summary><pre>${esc(JSON.stringify(c.old,null,2))}</pre></details></td><td><details><summary>查看新值</summary><pre>${esc(JSON.stringify(c.new,null,2))}</pre></details></td><td>${esc(c.effective)}</td></tr>`).join('')}</tbody></table></div><div class="actions">${evidenceLink(l.evidenceIds)}</div></article>`).join('')||'<div class="empty">初始版本。逐项审核发布后显示差异记录。</div>'}</section>`;}
function poolView(){return `<section class="panel"><div class="panel-head"><h2>本地人才池 · ${db.pool.length} 人</h2>${info('pool')}</div>${db.pool.map(id=>person(id)).filter(Boolean).map(p=>personCard(p)).join('')||'<div class="empty">从人才详情或查询结果加入人员。</div>'}<hr class="divider"><h3>关注项目 · 本轮仅本地保存</h3>${db.follows.map(id=>`<div class="task">${projectLink(id)}${action('follow','取消关注',`data-id="${id}"`)}</div>`).join('')||'<p class="muted">尚未关注项目。</p>'}</section>`;}
function dataView(){return `<section class="panel"><div class="panel-head"><h2>保留 V1，独立维护 V2</h2>${info('migration')}</div><p>不会把旧人物改名或将旧任职混入新的虚构世界。V1 的浏览器数据和交付备份均保留。</p><div class="actions">${action('exportLegacy','导出 V1 原始备份','','btn secondary')}${action('exportV2','导出当前 V2 数据','','btn')}${action('restoreBackup','恢复最近一次本地备份','','btn secondary')}</div><form id="importForm" class="section-space"><label class="field">导入 V2 JSON 备份（先校验，不自动写入）<textarea name="json" required placeholder="粘贴导出的完整 V2 JSON"></textarea></label><div class="actions"><button class="btn secondary">校验并预览导入</button>${info('storage')}</div></form><hr class="divider"><h3>重新演示</h3><p class="muted">重置前先保存可恢复的本地快照，并再次确认。不会清除 V1 数据。</p>${action('reset','备份后恢复 V2 初始样本','','btn danger')}</section>`;}
function about(){return `<section class="panel"><h2>V3.4.0：在证据底座之上补齐“所以呢 / 下一步做什么”</h2><p>保留 V3.0 的“录入 → 提案 → 人审 → 发布 → 查询 → 证据 → 版本”闭环与字段级证据。本轮新增：情报驾驶舱（KPI 变化量、窗口信号、数据健康度）、事件“信号 → 判断 → 建议行动”（判断层与事实分开存储、不进入查询）、由已发布任职自动计算的人才流向与去向未收录、项目 × 能力热力图、项目架构演变时间轴与项目关系图谱、招聘需求 → 可解释分层长名单，以及带状态 / 负责人 / 复核日期的可行动人才池。</p><div class="hint">全部资料虚构。${db.companies.length} 家公司、${db.projects.length} 个项目、${db.people.length} 位人物。没有真实招聘平台、候选人联系方式、真实求职意向、实时 AI 或每日推送；研判与跟进状态是 HRBP 工作记录，不是人员事实。</div><h3 class="section-space">3 分钟演示</h3><ol><li>驾驶舱先看 P0 窗口信号：《星海纪元》收缩，事实与判断分层展示；点开“去向与流动”。</li><li>录入第一条林序访谈。正式查询尚只命中顾航。</li><li>核对林序 ID，三条任职确认，关系暂缓或拒绝。</li><li>发布：新增两段历史；《云境》现有主策任职仅补证据。</li><li>组合查询新增林序；点击其《玄霄》2022年经历，展开战斗组，进入周岚与原文。</li><li>返回《云境》2024年，点击林序—许舟虚线核验来源；可暂缓或拒绝。</li><li>补充第二条材料可单独核定2022—2023组长头衔。查看版本及撤销。</li><li>需求长名单选择“主策（需战斗背景）”：林序进入 A 层，附命中依据、缺口与下一步核验；加入人才池并更新跟进状态。</li></ol><h3>状态分三层</h3><p>数据处理：待审核 / 已发布 / 已拒绝；事实核验：原文明确但单一来源 / 待核验 / 冲突；来源性质：虚构演示资料。人工发布不会自动升级成独立交叉验证。</p><h3 class="section-space">信息与维护机制</h3><p class="muted">人员→任职→项目→公司；能力绑定任职与原文；关系单独记录主体、客体、项目、有效时期与依据。HRBP负责身份、修订和发布；事件、纠错触发核验任务。月度和季度维护仅为策略建议，没有后台任务。</p><table><thead><tr><th>环节</th><th>AI目标分工</th><th>人的职责</th></tr></thead><tbody><tr><td>提取</td><td>字段与原文定位</td><td>身份、时间、岗位和职责核对</td></tr><tr><td>比对</td><td>新增 / 重复 / 冲突建议</td><td>确认、修订、暂缓、拒绝</td></tr><tr><td>分析</td><td>有据路径和摘要</td><td>人力规划与招聘判断</td></tr></tbody></table><h3 class="section-space">提取 Prompt（嵌入式）</h3><div class="quote" id="promptText">${esc(window.submissionDocs?.prompt||'加载说明失败')}</div><div class="actions">${act('copyPrompt','复制 Prompt','','btn secondary')}${act('downloadPrompt','下载 Prompt','','btn secondary')}</div><details class="section-space"><summary>展开完整操作说明与交付边界</summary><div class="quote">${esc(window.submissionDocs?.guide||'')}</div></details><p class="muted">成功指标：复杂查询耗时、有来源的关键事实比例、待核验任务量、错误合并数和纠错回流；本原型不伪造指标达成值。</p></section>`;}
function openModal(type,id='',extra={}){modalStack.push({type,id,...extra});renderModal();}
function renderModal(){const m=modalStack.at(-1);if(!m){$('#detail').close();return;}const contents={claim:claimDetail,sourceReview:sourceReviewDetail,person:personDetail,job:jobDetail,evidence:evidenceDetail,relation:relationDetail,event:eventDetail,compare:compareDetail,teamHistory:teamHistoryDetail,task:taskDetail,help:helpDetail,news:newsDetail,rawDraft:rawDraftDetail,correction:correctionDetail,undo:undoDetail,reset:resetDetail,import:importDetail,summary:summaryDetail,...(window.extraModals||{})};const [title,body]=contents[m.type](m);$('#detail').classList.toggle('drawer',m.type==='person'||m.type==='evidence'||m.type==='relation');$('#detailBody').innerHTML=`<div class="modal-head"><div>${modalStack.length>1?act('modalBack','← 返回上一层')+'<br>':''}<h2>${title}</h2></div>${act('close','×','aria-label="关闭详情"','close')}</div><div class="modal-body">${body}</div>`;if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;}
function personDetail(m){const p=person(m.id),js=jobs(p.id).sort((a,b)=>a.start-b.start),latest=js.at(-1),same=[...new Set(M.publishedJobs(db).filter(j=>j.personId!==p.id&&js.some(x=>x.projectId===j.projectId&&Math.max(x.start,j.start)<=Math.min(x.end??9999,j.end??9999))).map(j=>j.personId))];return [p.name+' · 人物档案',`<div class="row spread">${tag(p.id)}${action('pool',db.pool.includes(p.id)?'已加入人才池 ✓':'＋ 加入人才池',`data-id="${p.id}"`,'btn secondary')}${action('persona','查看人才画像',`data-id="${esc(p.id)}"`,'btn secondary','persona')}</div><h3 class="section-space">最近已知任职</h3><p>${latest?db.companies.find(c=>c.id===project(latest.projectId).companyId).name+' / '+project(latest.projectId).name+' · '+M.roleAt(latest,'all',db):'未知'}</p><p class="muted">${p.identity}。结束未知不表示确认现任；求职意向未知。</p><h3 class="section-space">关键经历与历史组织</h3><div class="timeline">${js.map(j=>`<section class="timeline-item"><span class="muted">${timeText(j)} · ${project(j.projectId).studio}</span><h3>${esc(M.roleAt(j,'all',db))}</h3><p>${esc(fieldValue(j,'module'))} · ${esc(fieldValue(j,'scope'))}</p><div class="actions">${action('project',`《${project(j.projectId).name}》${j.projectId==='G-A1'&&p.id==='P-A01'?2022:j.start}年组织 →`,`data-id="${j.projectId}" data-period="${j.projectId==='G-A1'&&p.id==='P-A01'?2022:j.start}" data-person="${p.id}"`,'link','period')}${action('job','任职与字段依据',`data-id="${j.id}" data-year="all"`,'link','evidence')}</div>${stateTags(j)}${j.notes?`<p class="muted">${esc(j.notes)}</p>`:''}</section>`).join('')}</div><h3>能力与责任范围</h3>${js.flatMap(j=>caps(j).map(c=>`<div class="record"><h3>${c.domain} · ${c.details.join(' / ')}</h3><p class="muted">${c.scope} · ${c.scenario}<br>对应 ${project(j.projectId).name}，任职 ${j.id}</p>${evidenceLink(c.evidenceIds)}</div>`)).join('')||'<p class="muted">尚无明确职责能力依据，不能从岗位推断。</p>'}<div class="hint">信息缺口：团队人数、私人联系方式、求职意向均未知。${p.id==='P-A01'?'玄霄负责小组工作的起始年与直接汇报仍待核验；正式组长头衔只能按有据时期展示。':''}</div><h3 class="section-space">同期同项目人员 ${info('related')}</h3>${same.map(id=>action('person',person(id).name,`data-id="${id}"`,'btn secondary')).join(' ')||'<p class="muted">暂无同期人员证据。</p>'}<p class="muted">仅按任职时间交集产生发现线索，不推断熟人或合作。</p>${db.relationships.map(r=>M.relationshipView(db,r)).filter(r=>(r.subjectId===p.id||r.objectId===p.id)&&r.processStatus!=='已拒绝').map(r=>`<p>${action('relation',`${person(r.subjectId).name}—${person(r.objectId).name}：${r.type} / ${r.processStatus}`,`data-id="${r.id}"`)}</p>`).join('')}<div class="actions">${action('correction','创建人物核验任务',`data-id="${p.id}" data-kind="person"`,'link','correction')}</div>`];}
function jobDetail(m){const j=db.jobs.find(j=>j.id===m.id);return ['任职详情 · '+esc(M.roleAt(j,m.year||'all',db)),`<p>${action('person',person(j.personId).name,`data-id="${j.personId}"`)} / ${projectLink(j.projectId,j.start,j.personId)}</p>${stateTags(j)}<p class="muted">ID ${j.id} · ${timeText(j)}<br>岗位原文：${esc(j.rawRole)}<br>职责：${esc(fieldValue(j,'module'))}<br>责任范围：${esc(fieldValue(j,'scope'))}<br>审核时间：${esc(j.reviewedAt)}</p>${j.notes?`<div class="hint">${esc(j.notes)}</div>`:''}<h3 class="section-space">头衔有效时期</h3>${j.roleHistory.length?j.roleHistory.filter(h=>M.supported(db,h)).map(h=>`<p>${h.start}–${h.end} ${esc(h.role)} ${evidenceLink(h.evidenceIds)}</p>`).join(''):'<p class="muted">无单独头衔变更证据，不回填未知时期。</p>'}<h3>字段级证据（点击查看具体依据）</h3>${claimLinks(M.rawClaims(db,j.id).map(c=>c.id))}<h3 class="section-space">关联原文</h3>${evidenceLink(j.evidenceIds)}`];}
function evidenceDetail(m){const e=evidence(m.id),cs=db.fieldClaims.filter(c=>c.sourceId===e.id);return ['原文与具体支持字段',`${tag(e.id)} ${tag(e.quarantined?'已隔离':'可用',e.quarantined?'amber':'green')}<h3>${esc(e.title||e.source)}</h3><div class="quote">${esc(e.text)}</div><p class="muted">来源类型 ${esc(e.kind||e.nature)}<br>发布 ${esc(e.published)} ／采集 ${esc(e.collected)}<br>独立性 ${esc(e.independence)} · ${esc(e.factStatus)}<br>${esc(e.quarantineReason||'')}</p><div class="hint">每个字段独立判断。本材料存在不代表它支持整条履历；批准演示材料不等于多源核实。</div><h3>字段主张</h3>${cs.map(c=>`<div class="record">${action('claim',esc(M.fieldLabels[c.field])+'：'+esc(c.value??'未知'),`data-id="${c.id}"`,'link','evidence')} ${tag(M.claimUsable(db,c)?'有效':'不作为已知事实')}<p>${esc(c.quote)}</p>${tag(c.basis)}</div>`).join('')||'<p>无正式任职字段主张；来源可能用于项目、关系或待核验线索。</p>'}${db.relationships.filter(r=>r.evidenceIds.includes(e.id)).map(r=>`<p>${action('relation',r.type,`data-id="${r.id}"`)}</p>`).join('')}${role==='hr'?action('sourceReview',e.quarantined?'恢复该来源':'隔离该来源',`data-id="${e.id}"`,'btn secondary','sourceReview'):''}`];}

function relationDetail(m){const r=M.relationshipView(db,db.relationships.find(r=>r.id===m.id)),a=person(r.subjectId),b=person(r.objectId);return [`${a.name}与${b.name} · ${r.type}`,`${stateTags(r)}<p>${project(r.projectId).name} · ${timeText(r)}</p><h3>最初线索（永久保留）</h3><div class="quote">${esc(r.quote)}</div><p class="hint">${esc(r.gap)} 句式检查只能阻止明显误判，不能核实来源真实性、独立性或行政关系。</p>${evidenceLink(r.evidenceIds)}<h3 class="section-space">审核历史</h3>${(r.reviews||[]).map(x=>`<div class="record"><b>${esc({confirm:'人工批准演示显示',defer:'暂缓',reject:'拒绝'}[x.decision])}</b><p>${esc(x.note)} · ${esc(x.reviewer)} · ${esc(x.date)}</p>${x.quote?`<div class="quote">${esc(x.quote)}</div>`:''}${evidenceLink(x.sourceId)}</div>`).join('')||'<p>尚无完整来源审核记录。</p>'}${role==='hr'?`<form id="relationForm"><input type="hidden" name="relationId" value="${r.id}"><label class="field">审核动作<select name="decision"><option value="defer">暂缓待核验</option><option value="reject">拒绝建立关系</option><option value="confirm">人工批准演示显示（单一来源）</option></select></label><label class="field">审核理由<textarea name="note" required></textarea></label><p class="muted">以下来源字段在确认时必须完整。暂缓、拒绝只需审核理由；请勿填写真实个人资料。</p><div class="formgrid">${[['kind','材料类型'],['title','来源标题'],['published','发布日期'],['collected','采集日期'],['reviewer','审核人（演示身份）']].map(([k,t])=>`<label class="field">${t}<input name="${k}" type="${['published','collected'].includes(k)?'date':'text'}"></label>`).join('')}<label class="field">来源独立性<select name="independence"><option>未核实</option><option>同源转述</option><option>声称独立，尚未核对</option></select></label><label class="field">有效开始年份<input name="start" type="number" value="${r.start}" min="2018" max="2026"></label><label class="field">结束年份（未知留空）<input name="end" type="number" value="${r.end??''}"></label></div><label class="field">来源全文<textarea name="sourceText"></textarea></label><label class="field">直接支持关系的逐字引文<textarea name="quote"></textarea></label><label class="checks"><span><input type="checkbox" name="approved">我核对了双方、项目、有效期和原文，仅批准虚构演示显示；未完成独立交叉核验。</span></label><div id="relationError" class="error" hidden></div><div class="actions"><button class="btn">保存关系审核</button>${info('relation')}</div></form>`:'<p class="hint">业务视角只读，由 HR 核验。</p>'}`];}

function compareBody(pid,before,after){const p=project(pid),old=M.projectJobs(db,pid,before),next=M.projectJobs(db,pid,after);return `<p class="muted">${p.name} · 快照按当前已发布事实回算，不是两个独立保存的全量组织。按年判断，未知月份不补齐。</p><div class="compare-grid">${[[before,old,next],[after,next,old]].map(([year,list,other])=>`<section class="compare-side"><h3>${year} 年 · ${M.stageAt(p,year)}</h3><p class="muted">${new Set(list.map(j=>j.personId)).size} 位已识别</p>${list.map(j=>`<article class="record ${!other.some(x=>x.id===j.id)?'changed':''}"><div class="row spread">${action('person',person(j.personId).name,`data-id="${j.personId}"`)}${!other.some(x=>x.id===j.id)?tag(other.some(x=>x.personId===j.personId)?(year===before?'原岗位结束 · 人员延续':'岗位职责变更'):(year===before?'此段任职结束':'本年新增任职'),'amber'):tag('延续')}</div><p>${esc(M.roleAt(j,year,db))}</p><p class="muted">${esc(fieldValue(j,'module'))} · ${j.id}</p>${evidenceLink(j.evidenceIds)}</article>`).join('')||'<p class="empty">该时期没有足够资料，不显示为真实岗位空缺。</p>'}</section>`).join('')}</div><div class="hint">所选年份的岗位变动不证明两人直接交接、汇报或离职意向。${pid==='G-A1'?'林序玄霄末年基于2024迁移边界推定，保留时间缺口。':'资料未收录不代表实际无人任职。'}</div>`;}
function compareDetail(m){const [before,after]=M.comparisonYears(db,m.id,projectState.period);return ['组织变化前后 · '+project(m.id).name,compareBody(m.id,before,after)];}
function eventDetail(m){const e=db.events.find(e=>e.id===m.id);return [e.title,`<p class="muted">发生 ${e.date} · 公开 ${e.published} · 采集 ${e.collected}</p><h3>材料直接陈述</h3><p>${esc(e.fact)}</p><h3 class="section-space">信息缺口 / 下一步核验</h3><p>${esc(e.gap)}</p>${evidenceLink(e.evidenceIds)}<div class="actions">${projectLink(e.projectId,e.before)}${e.relatedProjectId?projectLink(e.relatedProjectId,e.after):''}</div><h3 class="section-space">受影响的正式事实</h3><p class="muted">${(e.jobIds||[]).join('、')||'仅线索，尚无正式修改'}${e.logId?' · 版本记录 '+e.logId:' · 初始演示资料，无本次发布日志'}</p>${compareBody(e.projectId,e.before,e.after)}${role==='hr'?action('nav','查看版本差异','data-page="logs"','link','logs'):''}`];}
function teamHistoryDetail(m){return [project(m.id).name+' · '+esc(m.team)+'历史',M.projectJobs(db,m.id).filter(j=>j.team===m.team).sort((a,b)=>a.start-b.start).map(j=>`<div class="record"><h3>${action('person',person(j.personId).name,`data-id="${j.personId}"`)} · ${esc(M.roleAt(j,'all',db))}</h3><p class="muted">${timeText(j)}</p>${projectLink(m.id,j.start,j.personId)} ${evidenceLink(j.evidenceIds)}</div>`).join('')];}
function taskDetail(m){const t=db.tasks.find(t=>t.id===m.id);return ['核验任务',`<h3>${esc(t.title)}</h3><p>${esc(t.reason)}</p><p class="muted">责任人 ${t.owner} · ${t.status}</p>${evidenceLink(t.evidenceIds||[])}${t.draftId?action('draft','返回对应事实审核',`data-id="${t.draftId}"`,'link','review'):''}${t.resolution?`<div class="quote">${esc(t.resolution)}</div>`:''}${role==='hr'?`<form id="taskForm"><input type="hidden" name="taskId" value="${t.id}"><label class="field section-space">处理结论（不会修改正式履历）<textarea name="resolution" required></textarea></label><div class="actions"><button class="btn">保存结论并关闭任务</button></div></form>`:''}`];}
function helpDetail(m){const h=helpRegistry[m.id];return ['功能说明 · '+h.title,`<h3>点击后看到</h3><p>${esc(h.see)}</p><h3 class="section-space">HRBP 业务价值</h3><p>${esc(h.businessValue)}</p><h3 class="section-space">数据依据与限制</h3><p>${esc(h.basisAndLimit)}</p>`];}
function newsDetail(){return ['演示近30天新采集资料',`<p class="muted">观察日 ${db.observationDate}，含观察日及之前29天，按演示采集日期计算，排除历史底库初始化；不代表新发生人员变动。</p>${M.activityMetrics(db).collected.map(e=>`<div class="task"><span>${esc(e.source)} · ${e.collected}</span>${evidenceLink(e.id)}</div>`).join('')}`];}
function rawDraftDetail(m){const d=db.drafts.find(d=>d.id===m.id);return ['提案原文与处理结果',`<p>${d.name} · ${d.status}</p><div class="quote">${esc(d.text)}</div>${d.facts.map(f=>`<div class="record"><b>${f.kind==='relation'?'同项目关系':esc(f.value.role)}</b> ${tag(f.status)}<p>${esc(f.reviewNote||f.note)}</p></div>`).join('')}`];}
function correctionDetail(m){return ['提交核验任务',`<form id="correctionForm"><input type="hidden" name="targetId" value="${m.id}"><input type="hidden" name="kind" value="${m.kind}"><label class="field">理由与材料依据<textarea name="reason" required></textarea></label><div class="actions"><button class="btn">提交待核验任务</button></div></form>`];}
function undoDetail(){return ['撤销最近一次正式变更',`<p>恢复该次变更前的事实、关系与事件。原始证据、处理记录与审计仍保留。</p><div class="actions">${act('undoConfirm','确认撤销','','btn danger')}${act('close','保留当前版本','','btn secondary')}</div>`];}
function resetDetail(){return ['备份后重置 V2 示例',`<p>先保存当前完整快照，再恢复初始虚构样本（${M.seed().people.length}位人物、${M.seed().companies.length}家公司、${M.seed().projects.length}个项目）。可在“数据与备份”恢复最近快照；V1 数据不变。</p><div class="actions">${act('resetConfirm','保存备份并重置','','btn danger')}${act('close','取消','','btn secondary')}</div>`];}
function importDetail(m){return ['导入预览',`<p>已校验：${m.data.people.length} 人、${m.data.projects.length} 项目、${m.data.jobs.length} 段任职、版本 V${m.data.revision}。</p><p class="muted">这是完整 V2 状态恢复，不是 AI 提案导入。旧V2将显式升级规则；异常未来来源保留并隔离。确认前自动备份当前数据。</p><div class="actions">${act('importConfirm','备份当前数据并恢复','','btn')}${act('close','取消','','btn secondary')}</div>`];}
function summaryDetail(){return ['本次审核已保存',`<div class="summary-grid">${[['新增',lastSummary.added],['更新 / 补证据',lastSummary.updated],['暂缓',lastSummary.deferred],['拒绝',lastSummary.rejected]].map(([t,n])=>`<div><b>${n}</b><span>${t}</span></div>`).join('')}</div><div class="hint">人工发布不等于事实独立交叉核验；暂缓或拒绝不新增正式任职。</div><div class="actions">${action('demoQuery','查询战斗＋主策','','btn','query')}${projectLink('G-A1','2022','P-A01')}${action('nav','查看版本差异','data-page="logs"','link','logs')}</div>`];}
function refresh(){save();render();if(modalStack.length)renderModal();}
const protectedActions=new Set(['draft','rawDraft','undo','undoConfirm','reset','resetConfirm','loadV2','importConfirm','restoreBackup','exportLegacy','exportV2']);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 if(role!=='hr'&&protectedActions.has(a))return toast('此动作仅在 HR 视角演示。');
 if(window.insightActions?.[a]&&window.insightActions[a](b)!==false)return;
 if(a==='nav')return go(b.dataset.page);if(a==='help')return openModal('help',b.dataset.key);if(a==='close'){modalStack=[];return $('#detail').close();}if(a==='modalBack'){modalStack.pop();return renderModal();}if(a==='back')return back();
 if(a==='upgrade'){try{const next=M.migrateDatabase(db);archive();persistState(next);db=next;migrationRequired=false;render();}catch(err){toast('迁移未完成，原数据未替换：'+err.message);}return;}
 if(a==='loadV2'){try{const next=M.seed();if(storage.getItem(KEY))archive();persistState(next);needsChoice=false;db=next;render();}catch(err){toast('加载失败，原存档未替换：'+err.message);}return;}
 if(a==='exportLegacy'){const raw=storage.getItem(M.LEGACY_KEY);if(!raw)return toast('本浏览器没有 V1 存档；交付包另附 V1 备份。');return download('MMO_Mapping_V1_原始备份.json',raw,'application/json');}
 if(a==='exportV2')return download('MMO_Mapping_V2_数据备份.json',JSON.stringify(db,null,2),'application/json');
 if(a==='restoreBackup'){const key=storage.getItem('mmo-mapping-v2-last-backup'),raw=key&&storage.getItem(key);if(!raw)return toast('尚无可恢复快照。');try{const data=JSON.parse(raw);M.validateDatabase(data);openModal('import','',{data:M.migrateDatabase(data)});}catch(err){toast(err.message);}return;}
 if(a==='importConfirm'){try{const next=M.clone(modalStack.at(-1).data);M.validateDatabase(next);archive();persistState(next);db=next;go('home');toast('已恢复备份，原状态仍保存在本地快照。');}catch(err){toast('恢复失败，原数据未替换：'+err.message);}return;}
 if(a==='project')return openProject(id,b.dataset.period||'all',b.dataset.person||'');
 if(['person','evidence','relation','event','compare','task','rawDraft','claim','sourceReview'].includes(a))return openModal(a,id);
 if(a==='job')return openModal('job',id,{year:b.dataset.year});if(a==='teamHistory')return openModal('teamHistory',id,{team:b.dataset.team});if(a==='correction')return openModal('correction',id,{kind:b.dataset.kind});
 if(a==='team'){const t=b.dataset.team;projectState.expanded=projectState.expanded.includes(t)?projectState.expanded.filter(x=>x!==t):[...projectState.expanded,t];return render();}
 if(a==='projectTab'){projectState.tab=b.dataset.tab;return render();}
 if(a==='demoQuery'){queryState={combat:true,chief:true,mode:'any'};return go('search');}
 if(a==='clearQuery'){queryState={};return render();}if(a==='cap'){queryState={capability:b.dataset.cap};return go('search');}
 if(a==='stat'){const k=b.dataset.key;if(k==='people'){queryState={};return go('search');}if(k==='news')return openModal('news');if(k==='review'&&role==='biz')return go('projects');return go(k);}
 if(a==='useDemo'){intakeText=M.SAMPLES.find(s=>s.id===b.dataset.kind).text;formError='';return render();}
 if(a==='draft'){draftId=id;return go('review');}
 if(a==='pool'||a==='follow'){const list=a==='pool'?db.pool:db.follows,i=list.indexOf(id);if(i>=0)list.splice(i,1);else list.push(id);refresh();return toast(i>=0?'已移出本地列表':'已保存到本地列表；没有发送通知');}
 if(a==='undo')return openModal('undo');if(a==='reset')return openModal('reset');
 if(a==='undoConfirm'){try{M.undo(db);save();go('logs');toast('已撤销；证据与审计继续保留。');}catch(err){toast(err.message);}return;}
 if(a==='resetConfirm'){try{const next=M.seed();archive();persistState(next);db=next;draftId='';queryState={};activeRequirementId='';requirementPoolFilter='';go('home');toast('已恢复初始虚构样本，重置前快照可恢复。');}catch(err){toast('备份或保存失败，未重置：'+err.message);}return;}
 if(a==='copyPrompt'){if(!navigator.clipboard)return toast('浏览器不支持自动复制，请选择原文复制或下载。');navigator.clipboard.writeText(window.submissionDocs.prompt).then(()=>toast('Prompt 已复制')).catch(()=>toast('浏览器不允许自动复制，请选择下方文本复制或下载。'));return;}
 if(a==='downloadPrompt')return download('PROMPT_V2.md',window.submissionDocs.prompt);
});
document.addEventListener('change',e=>{if(e.target.id==='role'){role=e.target.value;modalStack=[];$('#detail').close();render();}if(e.target.id==='period'){projectState.period=e.target.value;projectState.highlight='';render();}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.matches('form'))return;e.preventDefault();const f=new FormData(form),get=k=>String(f.get(k)??'').trim(),fid=form.getAttribute('id');
 if(fid==='quickSearch'){const text=get('query');queryState={text,combat:text.includes('战斗'),chief:text.includes('主策'),mode:'any'};return go('search');}
 if(fid==='searchForm'){const text=get('text');queryState={text,combat:f.has('combat')||text.includes('战斗'),chief:f.has('chief')||text.includes('主策'),mode:get('mode'),company:get('company'),project:get('project'),capability:get('capability'),year:get('year')};return render();}
 if(fid==='projectFilters'){indexState={company:get('company'),genre:get('genre'),phase:get('phase'),followed:f.has('followed'),changed:f.has('changed')};return render();}
 if(fid==='correctionForm'){db.tasks.push({id:M.id('T'),title:'资料核验：'+get('targetId'),reason:get('reason'),targetId:get('targetId'),owner:'HRBP',status:'待核验',evidenceIds:[],created:M.now()});save();modalStack=[];$('#detail').close();if(role==='hr')go('review');else toast('已提交给 HRBP；正式事实尚未修改。');return;}
 if(window.insightForms?.[fid])return window.insightForms[fid](f,get);
 if(role!=='hr')return toast('请切换 HR 视角处理。');
 if(fid==='extractForm'){intakeText=get('sourceText');try{if(db.drafts.some(d=>d.text===intakeText&&!['已撤销','已拒绝'].includes(d.status)))throw new Error('此原文已有提案，请在审核工作台继续处理。');const result=M.extractIntelligence({text:intakeText},{db}),d=result.draft;db.drafts.push(d);draftId=d.id;save();go('review');}catch(err){formError=err.message;render();}return;}
 if(fid==='reviewForm'){const original=db.drafts.find(d=>d.id===get('draftId')),d=M.clone(original);d.personId=get('personId');d.identityConfirmed=f.has('confirmed');try{d.facts.forEach((x,i)=>{if(['已发布','已拒绝'].includes(x.status))return;x.decision=get('decision'+i);x.overlapResolution=get('overlap'+i);x.reviewNote=get('note'+i);if(x.kind!=='relation'&&d.mode!=='ambiguous'){const changed=x.value.role!==get('role'+i)||x.value.start!==+get('start'+i)||String(x.value.end??'')!==get('end'+i);if(changed&&!x.reviewNote)throw new Error('修订岗位或时间时，请填写人工修订理由。');x.value.role=get('role'+i);x.value.start=+get('start'+i);x.value.end=get('end'+i)===''?null:+get('end'+i);if(x.kind==='job')x.value.capability=f.has('cap'+i);if(d.mode==='interview'&&x.value.projectId==='G-A1'&&x.value.role.includes('组长'))throw new Error('第一条材料未证明正式组长头衔，请保留未知，或用第二条材料补充2022—2023头衔。');}});lastSummary=M.publish(db,d);save();queryState={combat:true,chief:true};go('search');openModal('summary');}catch(err){formError=err.message;Object.assign(original,{facts:d.facts,personId:d.personId});save();render();}return;}
 if(fid==='relationForm'){try{M.reviewRelation(db,get('relationId'),get('decision'),get('note'),{kind:get('kind'),title:get('title'),published:get('published'),collected:get('collected'),text:get('sourceText'),quote:get('quote'),independence:get('independence'),reviewer:get('reviewer'),start:+get('start'),end:get('end')?+get('end'):null,approved:f.has('approved')});refresh();toast('关系审核与版本已更新；双方任职不变。');}catch(err){$('#relationError').hidden=false;$('#relationError').textContent=err.message;}return;}
 if(fid==='sourceReviewForm'){try{M.setSourceStatus(db,get('sourceId'),get('quarantined')==='true',get('reason'),get('reviewer'));save();modalStack.pop();render();renderModal();toast('来源状态已更新；所有相关字段与查询同步重算。');}catch(err){toast(err.message);}return;}
 if(fid==='taskForm'){const t=db.tasks.find(t=>t.id===get('taskId'));t.status='已关闭';t.resolution=get('resolution');t.resolvedAt=M.now();refresh();toast('任务已记结论；正式事实未自动修改。');return;}
 if(fid==='importForm'){try{const data=JSON.parse(get('json'));M.validateDatabase(data);openModal('import','',{data:M.migrateDatabase(data)});}catch(err){toast('导入校验失败：'+err.message);}return;}
});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){modalStack=[];$('#detail').close();}}});
$('#detail').addEventListener('cancel',()=>{modalStack=[];});
render();

function claimDetail(m){const c=db.fieldClaims.find(c=>c.id===m.id);return ['字段依据 · '+M.fieldLabels[c.field],`<h3>${esc(c.value??'未知')}</h3>${tag(c.basis)} ${tag(c.precision)} ${tag(M.claimUsable(db,c)?'当前可用':'不作为当前已知事实','amber')}<p>对应 ${person(c.personId).name} / ${project(c.projectId).name} / 任职 ${c.jobId}</p>${c.validFrom?`<p>仅支持 ${c.validFrom}–${c.validTo} 年</p>`:''}<div class="quote">${esc(c.quote)}</div><p>${esc(c.limitations||'仅支持上述字段；不自动扩展为岗位、能力或管理人数。')}</p>${evidenceLink(c.sourceId)}`];}
function sourceReviewDetail(m){const e=evidence(m.id);return ['来源可用性审核',`<p>仅改变该来源支持的字段、能力与关系；保留原始材料、独立来源和日志。可通过版本撤销恢复。</p><form id="sourceReviewForm"><input type="hidden" name="sourceId" value="${e.id}"><input type="hidden" name="quarantined" value="${!e.quarantined}"><label class="field">审核原因<textarea name="reason" required></textarea></label><label class="field">演示审核人<input name="reviewer" required></label><div class="actions"><button class="btn">确认${e.quarantined?'恢复':'隔离'}来源</button></div></form>`];}
